  "code": "import csv

def read_sales(path='sales.csv'):
    data = {}
    with open(path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            region = row['region']
            quarter = row['quarter']
            units = int(row['units'])
            if region not in data:
                data[region] = {}
            data[region][quarter] = units
    return data

sales = read_sales()
changes = {}
for region, quarters in sales.items():
    q1 = quarters.get('Q1')
    q2 = quarters.get('Q2')
    if q1 is None or q2 is None:
        continue
    change = q2 - q1
    changes[region] = change

# find most negative change
most_negative_region = min(changes, key=lambda k: changes[k])
most_negative_change = changes[most_negative_region]

print('Region changes (units):')
for region, change in changes.items():
    print(f'{region}: {change}')
print('\nRegion with the largest drop:')
print(f'{most_negative_region} fell by {abs(most_negative_change)} units (change: {most_negative_change})')
"
